"use strict";
const eraFilms=[
 {year:2001,title:'从太空望向地球 · NASA 年代影像',src:'https://svs.gsfc.nasa.gov/vis/a000000/a002200/a002255/a002255.mp4',source:'https://svs.gsfc.nasa.gov/2255',credit:'NASA/Goddard Space Flight Center Scientific Visualization Studio · Greg Shirah / Horace Mitchell / Marte Newcombe',license:'https://svs.gsfc.nasa.gov/help/',licenseLabel:'NASA 公共领域说明',provider:'NASA SVS'},
 {year:2004,title:'去火星的旅程与太阳风 · NASA 年代影像',src:'https://svs.gsfc.nasa.gov/vis/a000000/a002900/a002924/a002924_solarcme_c_NTSC.mp4',source:'https://svs.gsfc.nasa.gov/2924',credit:'NASA/Goddard Space Flight Center Scientific Visualization Studio · Tom Bridgman / Greg Shirah / Dan Spicer',license:'https://svs.gsfc.nasa.gov/help/',licenseLabel:'NASA 公共领域说明',provider:'NASA SVS'},
 {year:2006,title:'Elephants Dream · 大象之梦',src:'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4',source:'https://orange.blender.org/download/',credit:'© 2006 Blender Foundation / Netherlands Media Art Institute · Elephants Dream',license:'https://creativecommons.org/licenses/by/3.0/us/'},
 {year:2008,title:'Big Buck Bunny · 大雄兔',src:'https://archive.org/download/BigBuckBunny1280x720Stereo/big_buck_bunny_720_stereo.mp4',source:'https://peach.blender.org/download/',credit:'© 2008 Blender Foundation · Big Buck Bunny',license:'https://creativecommons.org/licenses/by/3.0/'}
];
function openEraMedia(){$("#modal").close();navigate({type:'media',name:`${year()}年影音与软件`,url:'archaeo://media'});}
function renderEraMedia(){
 const y=Number(year());
 const entries=(rows)=>rows.filter(r=>r[2]<=y).map(r=>`<div class="era-media-entry">${siteLink(r[0],r[1])}<small>${escapeHTML(r[3]||r[1])}</small></div>`).join('');
 const films=eraFilms.filter(f=>f.year<=y);
 return `<section class="era-media"><header class="media-head"><strong>影音 · 软件 · 读书</strong><span>${year()} 年的上网日常</span></header><nav class="center-nav"><button data-action="home">时光首页</button><button data-news-center>新闻中心</button><button data-year-step="-1">上一年</button><b>${year()}</b><button data-year-step="1">下一年</button></nav><p class="center-notice">入口随年份切换，旧网址仍在考古浏览器里查询快照。历史站点内的点播、下载、账号与 Flash 功能可能已经失效。</p><section class="winamp-player"><div class="winamp-title">◈ OLD DAYS PLAYER <small>原创合成配乐</small></div><div class="winamp-display"><span>♫ MEMORY CHANNEL</span><b>8 BIT / 30 SEC / LOOP</b><i>▂ ▅ ▃ ▇ ▄ ▆ ▂ ▅ ▃</i></div><div class="winamp-controls"><button data-music-toggle>${$('#retro-audio').paused?'▶ 播放配乐':'Ⅱ 暂停配乐'}</button><label>音量 <input type="range" min="0" max="100" value="35" id="music-volume" data-music-volume aria-label="配乐音量"></label></div><p>本站原创8位合成旋律，为演示营造氛围，不是当年的流行歌曲。需手动播放，可随时关闭。</p></section><h2>♪ 当年的音乐入口</h2><div class="era-media-grid">${entries([['百度MP3','mp3.baidu.com',2002,'搜索、试听与下载的年代'],['九天音乐','www.9sky.com',1999,'音乐门户旧址'],['一听音乐','www.1ting.com',2003,'在线听歌旧入口'],['千千静听','www.ttplayer.com',2002,'桌面播放器的记忆'],['酷狗','www.kugou.com',2004,'早期音乐软件官网'],['虾米音乐','www.xiami.com',2008,'音乐社区旧址']])}</div><h2>▷ 视频 · 宽频 · 动画</h2><div class="era-media-grid">${entries([['央视国际','www.cctv.com',1996,'电视台网站的历史页面'],['新浪宽频','video.sina.com.cn',2003,'宽频时代的视频入口'],['闪客帝国','www.flashempire.com',1999,'Flash 动画社区旧址'],['闪吧','www.flash8.net',2000,'动画与闪客文化旧址'],['土豆网','www.tudou.com',2005,'播客与视频分享'],['优酷','www.youku.com',2006,'当年的视频门户'],['56网','www.56.com',2005,'视频分享站点'],['AcFun','www.acfun.cn',2007,'早期弹幕社区'],['哔哩哔哩','www.bilibili.com',2010,'弹幕与创作社区']])}</div><h2>▧ 可以直接播放的开放影片</h2>${films.length?films.map((f,i)=>`<article class="era-film"><h3>${f.year} · ${escapeHTML(f.title)}</h3><video controls playsinline preload="none" aria-label="${escapeHTML(f.title)}" src="${f.src}"></video><p>${escapeHTML(f.credit)} · <a href="${f.source}" target="_blank" rel="noopener noreferrer">影片来源</a> · <a href="${f.license}" target="_blank" rel="noopener noreferrer">${escapeHTML(f.licenseLabel||"CC BY 许可")}</a></p><small>这是所选年份之前已发布的开放影片，用作年代影音资料，不代表当年的热门排行。流媒体由原始资料站提供，播放需要网络。</small></article>`).join(''):'<p>这一年份暂未整理可直接播放的授权影片。可以先探索上方的历史视频与动画站点；2006年起可观看已整理的开放动画。</p>'}<h2>▣ 桌面与手机软件旧址</h2><div class="era-media-grid">${entries([['QQ / OICQ','www.tencent.com',1998,'即时通信官网旧页'],['MSN','www.msn.com',1995,'聊天、门户与联系人'],['Winamp','www.winamp.com',1997,'MP3播放器官网旧页'],['RealPlayer','www.real.com',1995,'流媒体播放器官网旧页'],['Flash / Macromedia','www.macromedia.com',1996,'动画与网页工具时代'],['迅雷','www.xunlei.com',2003,'下载软件官网旧页'],['UC浏览器','www.ucweb.com',2004,'手机上网的老朋友'],['Opera Mini','www.operamini.com',2006,'压缩网页与省流量'],['华军软件园','www.onlinedown.net',1997,'软件目录的历史存档'],['天空软件站','www.skycn.com',1998,'软件下载站旧址']])}</div><h2>▤ 小说 · 连载 · 书架</h2><div class="era-media-grid">${entries([['榕树下','www.rongshuxia.com',1997,'网络文学社区'],['红袖添香','www.hongxiu.com',1999,'原创文学与连载'],['起点中文网','www.qidian.com',2002,'网络小说书架'],['晋江文学城','www.jjwxc.net',2003,'当年的连载与讨论'],['潇湘书院','www.xxsy.net',2001,'文学阅读旧址'],['幻剑书盟','www.hjsm.net',2001,'玄幻与网络文学'],['小说阅读网','www.readnovel.com',2004,'小说阅读门户'],['17K小说网','www.17k.com',2006,'原创连载平台']])}</div><div class="media-play-scenes"><button data-scene="novels">打开本站原创小说阅读器</button><button data-scene="garden">去家园种菜</button><button data-scene="wutang">精武堂闯关</button></div><p class="scene-note">这里收集的是年代入口，不提供历史商业软件安装包，也不保证旧站服务仍可使用。欢迎附来源补充能公开播放的旧影像与可阅读作品。</p></section>`;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-era-media],[data-music-toggle]');if(!b)return;e.preventDefault();
 if(b.hasAttribute('data-era-media'))return openEraMedia();
 const audio=$('#retro-audio'),legacyVolume=$('#music-volume');if(legacyVolume)audio.volume=Number(legacyVolume.value)/100;
 if(!audio.paused){audio.pause();document.querySelectorAll('[data-music-toggle]').forEach(x=>x.textContent=x.hasAttribute('data-music-compact')?'♪':'▶ 播放配乐');}
 else audio.play().then(()=>document.querySelectorAll('[data-music-toggle]').forEach(x=>x.textContent=x.hasAttribute('data-music-compact')?'Ⅱ':'Ⅱ 暂停配乐')).catch(()=>toast('音频暂时无法播放，请再点一次或检查声音设置'));
});
document.addEventListener('input',e=>{if(e.target.hasAttribute?.('data-music-volume'))$('#retro-audio').volume=Number(e.target.value)/100;});
